import "server-only";

import type { Prisma } from "@/generated/prisma/client";
import {
  billingConfig,
  BillingError,
  BILLING_PRICES,
} from "@/lib/billing/config";
import { dodoClient } from "@/lib/billing/dodo";

export const openCheckoutStates = [
  "CREATING",
  "CUSTOMER_CREATING",
  "READY",
  "UNKNOWN",
];
export const nonRenewingStates = ["CANCELLED", "EXPIRED", "FAILED"] as const;

// Call only inside a short owner-locked transaction. This singleton is service
// configuration, not user data. Never adopt pre-existing unbound provider data.
export async function ensureBillingBinding(tx: Prisma.TransactionClient) {
  const config = billingConfig();
  await tx.$queryRaw`SELECT id FROM "SystemControl" WHERE key = 'global' FOR UPDATE`;
  const control = await tx.systemControl.findUnique({
    where: { key: "global" },
  });
  if (!control) throw new BillingError("BILLING_CONTROL_MISSING");
  if (control.dodoEnvironment === null && control.dodoBusinessId === null) {
    if (
      (await tx.billingSubscription.count()) ||
      (await tx.checkoutAttempt.count()) ||
      (await tx.user.count({ where: { dodoCustomerId: { not: null } } }))
    )
      throw new BillingError("BILLING_BINDING_REVIEW_REQUIRED");
    await tx.systemControl.update({
      where: { key: "global" },
      data: {
        dodoEnvironment: config.environment,
        dodoBusinessId: config.businessId,
      },
    });
  } else if (
    control.dodoEnvironment !== config.environment ||
    control.dodoBusinessId !== config.businessId
  ) {
    throw new BillingError("BILLING_BINDING_MISMATCH");
  }
}

export async function verifyBillingProduct() {
  const config = billingConfig();
  const client = dodoClient();
  const [product, localized] = await Promise.all([
    client.products.retrieve(config.productId),
    client.products.localizedPrices.list(config.productId),
  ]);
  const india = localized.items[0];
  if (
    product.business_id !== config.businessId ||
    product.product_id !== config.productId ||
    !product.is_recurring ||
    product.price.type !== "recurring_price" ||
    product.price.payment_frequency_count !== 1 ||
    product.price.payment_frequency_interval !== "Month" ||
    (product.price.trial_period_days ?? 0) !== 0 ||
    product.price.price !== BILLING_PRICES.USD ||
    product.price.currency !== "USD" ||
    product.pricing_mode !== "by_country" ||
    product.price.tax_inclusive !== true ||
    product.price.subscription_period_count !== 20 ||
    product.price.subscription_period_interval !== "Year" ||
    (product.price.discount ?? 0) !== 0 ||
    (product.price.discount_bps ?? 0) !== 0 ||
    product.price.purchasing_power_parity === true ||
    (product.price.trial_amount ?? 0) !== 0 ||
    (product.addons?.length ?? 0) !== 0 ||
    localized.items.length !== 1 ||
    india?.product_id !== config.productId ||
    india.mode !== "by_country" ||
    india.country_code !== "IN" ||
    india.currency !== "INR" ||
    india.amount !== BILLING_PRICES.INR
  )
    throw new BillingError("BILLING_PRODUCT_MISMATCH");
  return product;
}
